CREATE OR REPLACE FUNCTION public.life_pilot_edge_map_target(p_table_name text, p_event_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_result jsonb; v_visible text;
begin
  if auth.uid() is null then raise exception 'Authentication required' using errcode='42501'; end if;
  if p_table_name not in ('calendar_events','memory_trace','recommended_events','recommended_attractions') or nullif(p_event_id,'') is null then raise exception 'Invalid target'; end if;
  v_visible:='lower(trim(account))=public.life_pilot_user_email()';
  if p_table_name in ('recommended_events','recommended_attractions') then v_visible:='('||v_visible||' or coalesce(is_approved,false) or public.life_pilot_is_admin())'; end if;
  execute format('select jsonb_build_object(''id'',id,''country'',country,''city'',city,''location'',location,''map_lat'',map_lat,''map_lng'',map_lng) from public.%I where id::text=$1 and (%s)',p_table_name,v_visible) into v_result using p_event_id;
  if v_result is null then raise exception 'Event not found or not visible' using errcode='42501'; end if;
  return v_result;
end $function$
